    'RegistrationText'=>'Регистрираните екземпляри на SimpleRisk получават незабавно достъп до Extras за надграждане (Upgrade) и Secure Controls Framework (SCF).  Extra за надграждане дава възможност да архивирате и надграждате своя екземпляр на SimpleRisk с едно щракване.  Extra Secure Controls Framework (SCF) предоставя обща контролна рамка, интегрирана във функционалността за управление на SimpleRisk.  При регистриране на SimpleRisk Вашата регистрационна информация ще бъде изпратена до сървър, хостван от SimpleRisk.  Предоставената регистрационна информация ще се използва от SimpleRisk, за да уведомява клиентите за нови издания и актуализации на сигурността.  Регистрирането на SimpleRisk ще Ви включи в нашите маркетингови съобщения, но можете да се отпишете по всяко време чрез връзката за отписване в тези съобщения.  SimpleRisk зачита поверителността на своите клиенти и информацията, предоставена ни чрез процеса на регистрация в SimpleRisk, никога няма да бъде продавана на трети страни.',
