    'AdminRoleDescription' => 'Това разрешение осигурява достъп до конфигурациите на SimpleRisk. Потребител с това разрешение на практика е администратор на системата. Той може да прави промени във всички менюта в меню "Конфигуриране". Това разрешение позволява и активиране и деактивиране на допълнения (Extras) и промяна на техните конфигурации. Това разрешение трябва да се дава само на тези, които абсолютно се нуждаят от него. След като потребителят получи достъп до това разрешение, той ще може да редактира и други потребителски акаунти.',
