    'SettingsPreferencesDesc'             => 'Стойности по подразбиране и предпочитания за поведение в SimpleRisk: език, часова зона, състояния на одит, изисквания за картографиране на риска, превключватели за поведение на потребителския интерфейс и други подобни.',
    'SettingsFileUploadDesc'              => 'Разрешени типове файлове за качване и ограничения на размера за различните полета за прикачване на файлове.',
    'SettingsMailDesc'                    => 'SMTP конфигурация за изходящи имейл известия, включително транспорт, хост, удостоверяване и адрес за отговор.',
    'SettingsBackupsDesc'                 => 'Конфигуриране на срока на съхранение, графика и връзките за изтегляне на резервните копия на базата данни на SimpleRisk.',
    'SettingsSecurityDesc'                => 'Настройки за сигурност на удостоверяването, сесията, политиката за пароли, базовия URL адрес и API.',
    'SettingsLoggingDesc'                 => 'Конфигурация на дневниците за отстраняване на грешки и одит: нива на дневниците, срок на съхранение и местоположение на файловете с дневници.',
    'HealthCheckDesc'                     => 'Диагностика на състоянието на системата: версия на PHP, разширения, разрешения за файлове, свързаност с базата данни, график на cron и активации на Extra.',
    'AnnouncementsDesc'                   => 'Съставяйте и управлявайте банерни съобщения, видими за всички потребители.',
    'RegisterAndUpgradeDesc'              => 'Регистрирайте вашата инсталация на SimpleRisk, въведете или подновете абонаментен ключ и задействайте Core/Extra надстройки с едно щракване.',
    'QueueMonitorDesc'                    => 'Проверете опашката от фонови задачи: чакащи, изпълняващи се и неуспешни задачи.',
    'ExtrasDesc'                          => 'Активирайте, деактивирайте и конфигурирайте SimpleRisk Extras (платени добавки).',
    'ArtificialIntelligenceExtraDesc'     => 'Допълнителният модул „Изкуствен интелект“ предоставя подобрен анализ на риска (включително FAIR оценки) и персонализирана документация.',
    'CustomizationExtraDesc'              => 'Допълнителната функция за персонализиране дава възможност за добавяне и премахване на различни видове полета и динамично създаване на персонализирани шаблони за страници.',
    'NotificationExtraDesc'               => 'Extra „Имейл известия“ позволява на SimpleRisk да изпраща имейл известия, когато рисковете са подадени, променени или по друг начин обработени. Този Extra може да се добави и като планиран скрипт за изпращане на рутинни напомняния, когато рисковете са готови за преглед от ръководството. В продукта SimpleRisk Core, без този Extra, не се изпращат известия извън самия инструмент.',
    'VulnerabilityManagementExtraDesc'    => 'Extra „Управление на уязвимостите“ дава възможност на клиентите да интегрират своя екземпляр на SimpleRisk с Qualys, Tenable.io или Rapid7 Nexpose/InsightVM и да импортират в SimpleRisk данни както за активи, така и за уязвимости. След това можете да изберете кои сайтове да бъдат обхванати, да определите кои оценки на уязвимости да бъдат импортирани и да подредите по приоритет кои уязвимости да се превърнат в рискове, за да бъдат проследявани.',
    'IncidentManagementExtraDesc'         => 'Допълнителното решение за управление на инциденти е базирано на Ръководството за обработка на инциденти в областта на компютърната сигурност NIST 800-61 и предоставя възможности за управление на инциденти от системата SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Преименуване на терминологията на SimpleRisk (риск, актив, рамка и др.) в целия интерфейс.',
    'RiskConfigurationDesc'               => 'Конфигурирайте правила за оценка на риска: нива, апетит, прагове на SLA и класически/допринасящи формули за риск.',
    'RiskAndThreatCatalogDesc'            => 'Поддържайте каталога със стойности на риска и заплахата, използвани в падащите менюта.',
    'AddAndRemoveValuesDesc'              => 'Управление на стойностите в падащите списъци за полетата на риска: местоположение, източник, категория, екип, технология и други.',
    'AssetValuationDesc'                  => 'Конфигуриране на скалата за остойностяване на активи и на заместванията на оценката за отделните активи.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Добавяне, редактиране, деактивиране и нулиране на потребители; управление на политиката за пароли.',
    'RoleManagementDesc'                  => 'Дефинирайте ролите и разрешенията, които всяка роля предоставя.',
    'TeamManagementDesc'                  => 'Създавайте и управлявайте екипи, използвани за филтриране на видимостта на записите.',
    'SeparationExtraDesc'                 => 'Допълнителната опция за разделяне на базата на екип ограничава преглеждането на риска само до потребителите, които са членове на екипа, на който е присвоен рискът. В продукта SimpleRisk Core, без тази допълнителна опция, всеки потребител може да вижда всеки риск.',
    'CustomAuthenticationExtraDesc'       => 'Extra „Персонализирано удостоверяване“ осигурява поддръжка за Active Directory и SAML удостоверяване. В продукта SimpleRisk Core, без този Extra, единствената възможност е създаването на нови потребители в хранилището за идентичности на SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Encrypted Database Extra генерира произволен AES-256-битов ключ за криптиране и след това го използва, за да криптира чувствителен текст, преди да бъде вмъкнат в базата данни SimpleRisk. Това предотвратява възможността някой да преглежда или променя данните, без да използва директно приложението SimpleRisk.',
    'OrganizationManagementDesc'          => "Допълнителната функция „Организационна йерархия“ дава възможност за дефиниране на множество бизнес единици, които могат да включват произволен брой екипи. След това потребителите могат да бъдат разпределени в един или повече екипи под различни бизнес единици. Това влияе върху способността на потребителя да вижда и използва екипите, потребителите и активите, с които не е свързан.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Групово изтриване на рискове. Използвайте пестеливо — изтриванията са постоянни.',
    'AuditTrailDesc'                      => 'Търсене и експортиране на системния одитен дневник на действията на потребителите.',
    'ImportExportExtraDesc'               => 'Extra „Импортиране и експортиране“ предоставя възможност за импортиране на данни в SimpleRisk чрез съпоставяне на полета от CSV файл с полета в базата данни на SimpleRisk. Може да се използва за импортиране на резултати от одити от електронна таблица на трета страна, резултати от сканиране за уязвимости от друг инструмент, активи от вашата CMDB и други. Extra също така дава възможност за експортиране на CSV файлове от SimpleRisk, съдържащи рискове, смекчаване, прегледи или комбиниран отчет за трите.',
    'JiraExtraDesc'                       => 'Jira Integration Extra предоставя на потребителите възможността за двупосочна интеграция с Jira екземпляр. Тя позволява свързването на рискове с проблеми в Jira, както и синхронизирането на техните данни, статус и коментари.',
    'APIExtraDesc'                        => 'API Extra позволява на клиентите да използват RESTful API за създаване на скриптирани взаимодействия с други приложения, за да получат разширена автоматизация и да използват съществуващата инфраструктура.',
    'AdvancedSearchExtraDesc'             => 'Extra „Разширено търсене“ превръща полето за търсене в горната лента в единно търсене сред рискове, рамки, контроли, документи, изключения, тестове, одити, активи и групи активи, с пълна страница за търсене за работа с резултатите. Той показва само записите, които потребителят има разрешение да вижда.',
    'AssessmentsExtraDesc'                => 'Extra „Оценка на риска“ дава възможност на потребителите да дефинират контакти, да създават въпроси (включително с логика), да комбинират множество въпроси в шаблон на въпросник, да създават въпросници и да ги изпращат до контакти, да преглеждат резултатите от въпросниците, да добавят рискове въз основа на тези резултати и да сравняват резултатите във времето, да импортират и експортират външно персонализирани оценки и да преглеждат одитната следа на оценката на риска.',
    'ActiveAssessmentsDesc'               => 'Преглед и управление на оценките, които в момента са в ход.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra предоставя визуален, управляван от събития механизъм за работен процес, който автоматизира действията за управление на риска в отговор на събития в SimpleRisk. Можете да проектирате работни процеси, които се задействат при промени – като например подаване, актуализиране или преглед на риск – за насочване на одобрения, възлагане на работа и поддържане на процеса ви в движение без ръчна намеса.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Допълнението Secure Controls Framework (SCF) Extra е директна интеграция между Secure Controls Framework и SimpleRisk. То импортира каталога на SCF с контроли и техните картографирания към широк набор от рамки за съответствие и киберсигурност във функционалността за управление (Governance) на SimpleRisk, така че да можете да приемете необходимите рамки и да управлявате техните контроли, без да ги изграждате ръчно.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Мигрирайте наследените колони с дати на преглед от тип varchar към подходящи типове за дата. Видимо само когато е необходимо.',
    'DatabaseUpgradeDesc'                 => 'Ръчно задействайте процедурата за надграждане на базата данни SimpleRisk.',

