    'Help' => 'Помощ',
    'Profile' => 'Профил',
    'Scoring' => 'Оценяване',
    'EncryptionMissingLockTablesPrivilege'   => 'Потребителят на базата данни SimpleRisk няма привилегията LOCK TABLES, която е необходима за безопасното криптиране на базата данни. Помолете администратор на базата данни да изпълни командата GRANT, върната в отговора, и опитайте отново.',
    'EncryptionMissingLockTablesPrivilegeUi' => 'Потребителят на базата данни SimpleRisk няма привилегията LOCK TABLES, необходима за криптиране. Администраторът на базата данни трябва да изпълни: GRANT LOCK TABLES ON {$db}.* TO {$user}; след това опитайте отново.',
    'EncryptionRequiredGrantLabel' => 'Необходим израз GRANT:',
    'EncryptionActivationAlreadyRunning' => 'Активирането на криптиране вече се изпълнява. Изчакайте го да приключи или използвайте възстановяване от резервно копие.',
    'EncryptionActivationEnqueued'           => 'Активирането на Encryption Extra е поставено в опашка. Административният интерфейс ще следи напредъка, докато базата данни се криптира.',
    'EncryptionActivationEnqueueFailed'      => 'Неуспешно поставяне в опашка на задачата за активиране на криптиране. Вижте дневника за отстраняване на грешки за подробности.',
    'EncryptionDeactivationEnqueued'         => 'Деактивирането на Encryption Extra е поставено на опашка. Административният интерфейс ще следи напредъка, докато базата данни се дешифрира.',
    'EncryptionDeactivationEnqueueFailed'    => 'Неуспешно поставяне на задачата за деактивиране на криптиране в опашката. Проверете дневника за отстраняване на грешки за подробности.',
    'EncryptionPipelineInProgress'           => 'В момента се извършва процес на криптиране (активиране, деактивиране или възстановяване). Изчакайте да приключи, преди да опитате отново.',
    'EncryptionPipelineInProgressTask'       => 'В момента се изпълнява процес на криптиране (задача #{id}, {type}). Изчакайте да приключи, преди да опитате отново.',
    'EncryptionInFlightTitle'            => 'Операцията по криптиране е в ход',
    'EncryptionInFlightBody'             => 'В момента се изпълнява процес на активиране, деактивиране или възстановяване на криптиране. Изчакайте го да приключи — страницата ще се обнови автоматично, когато операцията завърши — преди да опитате отново.',
    'OK'                                 => 'Добре',
    'ActivationGuardFailed'                 => 'Активирането не можа да започне. Вижте предупреждението в заглавката на страницата за подробности.',
    'EncryptionStageStarting'               => 'Започва се…',
    'EncryptionStageProgress'               => 'Етап {current} от {total}: {name}',
    'EncryptionStageAllDone'                => 'Всички етапи са завършени.',
    'EncryptionStageEncryptTable'           => 'Криптиране на таблица: {table}',
    'EncryptionStageDecryptTable'           => 'Декриптиране на таблица: {table}',
    'EncryptionActivationInProgress'        => 'Криптиране на вашата база данни SimpleRisk. Моля, не затваряйте тази страница.',
    'EncryptionActivationFailedTitle'       => 'Активирането на криптирането е неуспешно',
    'EncryptionActivationFailedBody'        => 'Активирането не можа да бъде завършено и базата данни може да е в неконсистентно състояние. Резервното копие преди активирането е запазено — използвайте „Възстановяване от резервно копие“, за да възстановите, или се свържете с поддръжката на SimpleRisk.',
    'EncryptionDeactivationInProgress'      => 'Декриптиране на вашата база данни на SimpleRisk. Моля, не затваряйте тази страница.',
    'EncryptionDeactivationFailedTitle'     => 'Деактивирането на криптирането не бе успешно',
