    'EncryptionRestoreCtaHelp'              => 'Изберете това, ако валидирането е открило проблеми и трябва да се върнете към състоянието преди криптирането.',
    'EncryptionRestoreTitle'                => 'Възстановяване от резервно копие?',
    'EncryptionRestoreBodyWhy'              => 'Връщане към моментната снимка преди криптирането, заснета в началото на последното активиране. Изберете тази опция, ако проверката след активиране е открила проблеми и трябва да прекратите криптирането.',
    'EncryptionRestoreBodyWhat'             => 'Всеки запис, добавен в базата данни след създаването на резервното копие, ще бъде безвъзвратно загубен — включително рискове, смекчаване на рискове, записи в одитния журнал и всякакви други промени, направени след активирането. Допълнението „Криптирана база данни“ ще бъде деактивирано като част от възстановяването.',
    'EncryptionDeleteBackupCta'             => 'Изтриване на резервното копие преди криптирането',
    'EncryptionDeleteBackupCtaHelp'         => 'Изберете това, след като валидирането след криптиране приключи. Премахването на некриптираната снимка е това, което прави криптирането действително защитно.',
    'EncryptionDeleteBackupTitle'           => 'Да се изтрие ли резервното копие преди криптиране?',
    'EncryptionDeleteBackupBodyWhy'         => 'Премахване на некриптираната снимка на вашите данни, направена в началото на последното активиране. Запазването ѝ за неопределено време обезсмисля криптирането — всеки с достъп до базата данни може да прочете копието от преди криптирането.',
    'EncryptionDeleteBackupBodyWhat'        => 'Резервното копие в базата данни се изтрива незабавно. Вече няма да можете да използвате „Възстановяване от резервно копие“, за да върнете базата данни към състоянието преди криптирането. Ако по-късно откриете проблеми с криптирането, единственият ви начин за възстановяване ще бъде ново възстановяване на базата данни от вашите оперативни резервни копия.',
    'EncryptionDeleteBackupError'           => 'Изтриването на резервното копие не бе успешно. Проверете дневника за отстраняване на грешки и опитайте отново.',
