    'AssetScoring' => 'Оценка на активите',
    'AssetScoringSettingsHint' => 'Всеки актив се оценява като нисък, умерен или висок по отношение на поверителност, цялостност и наличност, а поверителността може да бъде и „Не е приложимо“, което я изключва и от двата резултата. FIPS категоризацията му е най-високата от трите оценки. Претеглената му оценка е претегленото средно на трите стойности на нивата, а праговете на диапазоните превръщат тази оценка в нисък, умерен или висок диапазон. Промяната на тези настройки преоценява веднага всеки актив.',
    'Weights' => 'Тежести',
    'AssetScoringWeightsHint' => 'Колко тежи всяка цел в претеглената оценка: от 0 до 100, с до два знака след десетичната запетая. Тегло 0 изключва тази цел. Цялостност и наличност не могат и двете да са 0, защото поверителност „Не е приложимо“ винаги се изключва.',
    'LevelValues' => 'Стойности на нивата',
    'AssetScoringLevelValuesHint' => 'Числото, с което всяка оценка участва в претеглената оценка: над 0 и до 100, с до два знака след десетичната запетая, като нисък е под умерен, а умерен е под висок. Стойностите по подразбиране са: нисък 1, умерен 2 и висок 3.',
    'BandThresholds' => 'Прагове на диапазоните',
    'AssetScoringBandThresholdsHint' => 'Претеглена оценка, равна на или над даден праг, попада в съответния диапазон, а оценка под прага за умерен е ниска. Умерен трябва да започва над стойността за нисък, а висок трябва да започва над умерен и не по-високо от стойността за висок.',
    'ModerateStartsAt' => 'Умерено започва от',
    'HighStartsAt' => 'Високото започва от',
    'DefaultScoringForNewAssets' => 'Оценяване по подразбиране за нови активи',
    'AssetScoringDefaultsHint' => 'Предварително избира тези оценки, когато някой добави актив във формуляра за активи. Активите, създадени чрез откриване, импортиране или API, остават без оценка, освен ако не предоставят свои собствени оценки. Оставете и трите опции „Не е зададено“, за да изключите това.',
    'AssetScoringWeightsInvalid' => 'Теглата за оценка на активите трябва да са числа от 0 до 100 с най-много два знака след десетичната запетая, а Целостта и Наличността не могат едновременно да бъдат 0.',
    'AssetScoringValuesInvalid' => 'Стойностите на нивата за оценяване на активи трябва да са числа над 0 и до 100 с най-много два знака след десетичната запетая, като нисък е под умерен, а умерен е под висок.',
    'AssetScoringThresholdsInvalid' => 'Праговете на диапазоните за оценяване на активи трябва да имат най-много два знака след десетичната запетая, като умерен започва над стойността за нисък, висок започва над умерен, а висок започва не по-високо от стойността за висок.',
