    'UserImportPasswordsShownOnce' => 'Тези временни пароли са изтрити от SimpleRisk и не могат да бъдат показани отново. Копирайте ги сега. Всеки потребител трябва да промени своята при първия си вход.',
    'UserImportPasswordsUnavailable' => 'Временните пароли вече не могат да бъдат показани. Те се показват веднъж, само на администратора, който е започнал импортирането, и само в раздела на браузъра, в който е започнато, а SimpleRisk не съхранява нищо, чрез което да бъдат показани отново. Задайте нова парола за всеки нов потребител чрез редактиране на потребителя.',
    'UserImportBackgroundNote' => 'Тази страница се актуализира автоматично и импортирането продължава да се изпълнява, ако излезете. Отворете страницата отново, за да видите резултата.',
